{"path": "solution.py", "content": "def int_to_roman(n):
    """Convert an integer in [1, 3999] to a Roman numeral string.

    Uses standard subtractive notation (4 = IV, 9 = IX, 40 = XL, ...).
    Raises ValueError if n is outside the valid range or not an integer.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")

    val_sym = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    parts = []
    for value, sym in val_sym:
        while n >= value:
            parts.append(sym)
            n -= value
    return "".join(parts)
"}

