{"path": "solution.py", "content": "def merge_intervals(intervals):
    """Merge overlapping/touching [start, end] intervals.

    Returns a new list of merged, sorted, non-overlapping intervals.
    The input list (and its inner lists) is never mutated.
    """
    if not intervals:
        return []

    # Copy each interval as a tuple and sort by start (then end).
    sorted_intervals = sorted((tuple(iv) for iv in intervals), key=lambda x: (x[0], x[1]))

    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            # Overlapping or touching: extend the last interval if needed.
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged
"}

