{"path": "solution.py", "content": "import re


def word_frequencies(text):
    """Return (word, count) tuples for words in text.

    Words consist of letters and apostrophes only; anything else splits.
    Words are lower-cased. Result is sorted by count descending, then
    word ascending.
    """
    if not text:
        return []

    counts = {}
    for match in re.finditer(r"[A-Za-z']+", text):
        word = match.group(0).lower()
        counts[word] = counts.get(word, 0) + 1

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))
"}

