{"path": "solution.py", "content": "def binary_search(items, target):
    """Return the index of the FIRST occurrence of target in sorted list items,
    or -1 if absent. Runs in O(log n)."""
    if not items:
        return -1

    low, high = 0, len(items) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2
        if items[mid] < target:
            low = mid + 1
        elif items[mid] > target:
            high = mid - 1
        else:
            result = mid  # record candidate, keep searching left half
            high = mid - 1

    return result
"}

