{"path": "solution.py", "content": "def moving_average(nums, k):
    """Return the averages (floats) of each window of k consecutive numbers.

    Uses a sliding window sum for O(n) time complexity.
    Raises ValueError if k < 1; returns [] if k > len(nums).
    """
    if k < 1:
        raise ValueError("k must be at least 1")
    n = len(nums)
    if k > n:
        return []

    result = []
    window_sum = 0
    for i, x in enumerate(nums):
        window_sum += x
        if i >= k:
            window_sum -= nums[i - k]
        if i >= k - 1:
            result.append(window_sum / k)
    return result
"}

