# Each unit (h, m, s) optional but must appear in order; digits required before each unit.
_PATTERN = re.compile(r'^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$')


def parse_duration(text):
    """Convert a duration string like '1h30m', '45s', '2h5s', '10m' to total seconds (int).

    Rules:
      - Units h, m, s may each appear at most once and only in that order.
      - Each unit must be preceded by one or more digits.
      - No whitespace is allowed.
      - Empty or malformed input raises ValueError.
    """
    if not isinstance(text, str) or not text:
        raise ValueError("duration must be a non-empty string")

    match = _PATTERN.match(text)
    if not match:
        raise ValueError("malformed duration: %r" % (text,))

    hours, minutes, seconds = match.groups()
    if hours is None and minutes is None and seconds is None:
        # Would only happen for an empty string, which we already rejected;
        # keep as a defensive guard against degenerate matches.
        raise ValueError("malformed duration: %r" % (text,))

    total = 0
    if hours is not None:
        total += int(hours) * 3600
    if minutes is not None:
        total += int(minutes) * 60
    if seconds is not None:
        total += int(seconds)
    return total
