{"path": "solution.py", "content": "from collections import OrderedDict


class LRUCache:
    """Least Recently Used cache with O(1) get and put.

    Uses an OrderedDict where the most recently used item is kept at the end
    (via move_to_end). The first item in iteration order is the LRU candidate
    for eviction.
    """

    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 0:
            raise ValueError("capacity must be a non-negative integer")
        self.capacity = capacity
        self._store = OrderedDict()

    def get(self, key):
        if key not in self._store:
            return -1
        # Mark as recently used.
        self._store.move_to_end(key)
        return self._store[key]

    def put(self, key, value):
        if self.capacity == 0:
            # Cache cannot hold anything; ignore inserts.
            return
        if key in self._store:
            # Update existing key and mark as recently used.
            self._store.move_to_end(key)
            self._store[key] = value
        else:
            self._store[key] = value
            if len(self._store) > self.capacity:
                # Evict least recently used (first item).
                self._store.popitem(last=False)
"}

